import {normalizeRegionZoom} from './region-zoom.js';
export function regionZoomDrag(initial,dx,dy,resize=false){return normalizeRegionZoom({...initial,...(resize?{zoomSize:initial.zoomSize+2*(Math.abs(dx)>Math.abs(dy)?dx:dy)}:{zoomX:initial.zoomX+dx,zoomY:initial.zoomY+dy})})}
export function bindRegionZoomFrame(frame,{getEffect,begin,change,finish}){frame.addEventListener('pointerdown',event=>{const effect=getEffect();if(!effect||event.button!==0||event.isPrimary===false)return;event.preventDefault();event.stopPropagation();const initial=normalizeRegionZoom(effect),rect=frame.parentElement.getBoundingClientRect(),x=event.clientX,y=event.clientY,resize=event.target.closest('[data-zoom-resize]');begin();frame.setPointerCapture(event.pointerId);frame.onpointermove=ev=>{const dx=(ev.clientX-x)/rect.width,dy=(ev.clientY-y)/rect.height;change(regionZoomDrag(initial,dx,dy,resize));};const end=ev=>{frame.onpointermove=frame.onpointerup=frame.onpointercancel=null;try{frame.releasePointerCapture(ev.pointerId)}catch{}finish(ev.type==='pointercancel',initial)};frame.onpointerup=end;frame.onpointercancel=end;});}
